public class Main {
  static void bump(int[] a, int n) {
    a[0] = a[0] + 1;
    n = n + 1;
  }
  public static void main(String[] args) {
    int[] arr = {1};
    int k = 1;
    bump(arr, k);
    System.out.println(arr[0] + " " + k);
  }
}

